    private function segmentComparable(array $rows): array{return array_map(fn($r)=>array_intersect_key($r,array_flip(['segment_type_code','started_at','ended_at','project_id','workplace_assignment_id'])),$rows);}
    private function aggregate(string $closure,string $employee,string $month,int $revision,array $rows,array $exceptions,string $reason,string $key,string $actor,string $now): array{$sum=fn($field)=>array_sum(array_map(fn($r)=>(int)$r[$field],$rows));$count=fn($type)=>count(array_filter($exceptions,fn($x)=>$x['exception_type_code']===$type));$hashRows=[];foreach($rows as $r){$ex=array_values(array_map(fn($x)=>$x['exception_type_code'],array_filter($exceptions,fn($x)=>$x['daily_record_id']===$r['id'])));sort($ex);$hashRows[]=['daily_record_id'=>$r['id'],'work_date'=>$r['work_date'],'scheduled_work_seconds'=>(int)$r['scheduled_work_seconds'],'actual_work_seconds'=>(int)$r['actual_work_seconds'],'calculated_overtime_seconds'=>(int)$r['calculated_overtime_seconds'],'night_work_seconds'=>(int)$r['night_work_seconds'],'holiday_work_seconds'=>(int)$r['holiday_work_seconds'],'exceptions'=>$ex,'calculation_version'=>(int)$r['calculation_version']];}$hash=hash('sha256',json_encode($hashRows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));return ['id'=>$this->uuid(),'monthly_closure_id'=>$closure,'revision'=>$revision,'employee_id'=>$employee,'closing_month'=>$month,'workday_count'=>count(array_filter($rows,fn($r)=>(int)$r['scheduled_work_seconds']>0)),'scheduled_work_seconds'=>$sum('scheduled_work_seconds'),'actual_work_seconds'=>$sum('actual_work_seconds'),'calculated_overtime_seconds'=>$sum('calculated_overtime_seconds'),'night_work_seconds'=>$sum('night_work_seconds'),'holiday_work_seconds'=>$sum('holiday_work_seconds'),'late_candidate_count'=>$count('LATE'),'late_candidate_seconds'=>$sum('late_candidate_seconds'),'early_leave_candidate_count'=>$count('EARLY_LEAVE'),'early_leave_candidate_seconds'=>$sum('early_leave_candidate_seconds'),'absence_candidate_days'=>$count('ABSENT'),'missing_clock_count'=>$count('MISSING_CLOCK_IN')+$count('MISSING_CLOCK_OUT'),'ledger_hash'=>$hash,'calculation_version'=>1,'close_reason'=>$reason,'closed_by'=>$actor,'closed_at'=>$now,'source_request_key'=>$key,'created_at'=>$now];}
    private function audit(string $domain,string $target,string $employee,string $action,string $source,string $reason,string $key,?array $before,?array $after,string $actor): void{$this->model->insert('institution_attendance_audits',['id'=>$this->uuid(),'attendance_domain'=>$domain,'target_id'=>$target,'employee_id'=>$employee,'action_type_code'=>$action,'source_type_code'=>$source,'reason'=>$reason,'request_key'=>$key,'before_data'=>$before?json_encode($before,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,'after_data'=>$after?json_encode($after,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,'processed_by'=>$actor,'processed_at'=>date('Y-m-d H:i:s')]);}
    private function assertOpen(string $employee,string $month): void{$c=$this->model->closure($employee,$month);if($c&&$c['close_status_code']==='CLOSED')throw new \RuntimeException('마감된 월은 변경할 수 없습니다. 먼저 마감을 해제해 주세요.');}
    private function required(mixed $v,string $m): string{$v=trim((string)$v);if($v==='')throw new \InvalidArgumentException($m);return $v;}
    private function key(array $in): string{return $this->required($in['request_key']??'','요청 키가 필요합니다.');}
    private function date(mixed $v): string{$v=$this->required($v,'근무일을 입력해 주세요.');$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new \InvalidArgumentException('근무일 형식이 올바르지 않습니다.');return $v;}
    private function month(mixed $v): string{$v=$this->required($v,'귀속월을 입력해 주세요.');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$v))throw new \InvalidArgumentException('귀속월 형식이 올바르지 않습니다.');return $v;}
